/*
 * Prévia da paleta que o tema deriva da cor primária do Flarum.
 *
 * As amostras são pintadas pelo CSS do painel (less/admin/CanelaSettings.less)
 * com as mesmas fórmulas `oklch(from …)` de less/common/tokens.less — a prévia
 * é o próprio cálculo do fórum, não uma aproximação em JS. A cor entra por uma
 * variável no estilo, lida das configurações: assim a prévia acompanha a cor
 * gravada mesmo antes de o CSS do admin ser recompilado — e a amostra da cor
 * atual, dentro do mesmo bloco, nunca discorda das derivadas.
 */
import app from 'flarum/admin/app';
import { trans } from '../util';
const KEY = 'ramon-canela.admin.settings';

/** Só um hexadecimal entra no atributo `style`: o valor vem do banco. */
const HEX_COLOR = /^#(?:[0-9a-f]{3,4}|[0-9a-f]{6}|[0-9a-f]{8})$/i;
const SCHEMES = ['light', 'dark'];
const SWATCHES = [{
  key: 'accent',
  label: () => trans(`${KEY}.palette_accent`)
}, {
  key: 'background',
  label: () => trans(`${KEY}.palette_background`)
}, {
  key: 'selected',
  label: () => trans(`${KEY}.palette_selected`)
}, {
  key: 'accent-low',
  label: () => trans(`${KEY}.palette_accent_low`)
}, {
  key: 'ring',
  label: () => trans(`${KEY}.palette_ring`)
}, {
  key: 'link',
  label: () => trans(`${KEY}.palette_link`)
}];
const primaryColor = () => {
  const value = String(app.data.settings.theme_primary_color ?? '').trim();
  return HEX_COLOR.test(value) ? value : null;
};
export const PalettePreview = {
  view() {
    const color = primaryColor();
    return m("div", {
      className: "CanelaAdmin-palette",
      style: color ? `--cn-preview-accent: ${color}` : undefined
    }, m("div", {
      className: "CanelaAdmin-colorCurrent"
    }, m("span", {
      className: "CanelaAdmin-label"
    }, trans(`${KEY}.colors_current`)), m("span", {
      className: "CanelaAdmin-colorChip"
    }, m("span", {
      className: "CanelaAdmin-colorDot",
      "aria-hidden": "true"
    }), m("code", null, color ?? '-'))), SCHEMES.map(scheme => m("div", {
      key: scheme,
      className: `CanelaAdmin-paletteRow CanelaAdmin-paletteRow--${scheme}`
    }, m("span", {
      className: "CanelaAdmin-paletteScheme"
    }, scheme === 'light' ? trans(`${KEY}.palette_light`) : trans(`${KEY}.palette_dark`)), m("div", {
      className: "CanelaAdmin-swatches"
    }, SWATCHES.map(swatch => m("span", {
      key: swatch.key,
      className: "CanelaAdmin-swatch",
      "data-swatch": swatch.key
    }, m("span", {
      className: "CanelaAdmin-swatchColor",
      "aria-hidden": "true"
    }), m("span", {
      className: "CanelaAdmin-swatchLabel"
    }, swatch.label())))))));
  }
};
flarum.reg.add('ramon-canela', 'admin/components/PalettePreview', { PalettePreview: PalettePreview, });