/*
 * Acesso do admin de emblemas à API (`/api/canela-badges`, `/api/canela-user-badges`). O
 * admin não tem os modelos do fórum, então lê e grava o JSON:API direto.
 */
import app from 'flarum/admin/app';
import { trans } from '../../util';
export const KEY = 'ramon-canela.admin.settings.badges';
export const TYPES = ['gold', 'silver', 'bronze'];
export const GROUPINGS = ['getting_started', 'community', 'posting', 'trust_level', 'other'];
export const apiUrl = () => (app.forum.attribute('apiUrl') || '/api').replace(/\/+$/, '');

/** Os campos da migração do admin já existem (o servidor só os manda depois dela). */
export const hasAdminColumns = badge => !!badge && 'manualGrant' in badge.attributes;

/** O texto do primeiro erro de uma resposta 422, para mostrar dentro do modal. */
export function errorText(error) {
  const detail = error?.response?.errors?.[0]?.detail;
  return typeof detail === 'string' && detail ? detail : trans(`${KEY}.request_failed`);
}

/** Pedido sem o alerta automático do core: os modais mostram o erro no lugar. */
export function request(options) {
  return app.request({
    errorHandler: () => {},
    ...options
  });
}
export function loadBadges() {
  return request({
    method: 'GET',
    url: `${apiUrl()}/canela-badges`,
    params: {
      sort: 'position'
    }
  }).then(response => response.data);
}
export function saveBadge(id, attributes) {
  return request({
    method: id ? 'PATCH' : 'POST',
    url: id ? `${apiUrl()}/canela-badges/${id}` : `${apiUrl()}/canela-badges`,
    body: {
      data: {
        type: 'canela-badges',
        ...(id ? {
          id
        } : {}),
        attributes
      }
    }
  }).then(response => response.data);
}
export function deleteBadge(id) {
  return request({
    method: 'DELETE',
    url: `${apiUrl()}/canela-badges/${id}`
  });
}
export function restoreSystemBadges() {
  return request({
    method: 'POST',
    url: `${apiUrl()}/canela-badges/restore-system`
  }).then(response => response.meta?.restored ?? 0);
}
export function grantBadge(badgeId, username, reason) {
  return request({
    method: 'POST',
    url: `${apiUrl()}/canela-user-badges/grant`,
    body: {
      badgeId: Number(badgeId),
      username,
      reason
    }
  });
}
export function revokeGrant(id) {
  return request({
    method: 'DELETE',
    url: `${apiUrl()}/canela-user-badges/${id}`
  });
}

/** Uma página de concessões de um emblema, com o usuário de cada uma. */
export function loadGrants(badgeId, offset) {
  return request({
    method: 'GET',
    url: `${apiUrl()}/canela-user-badges`,
    params: {
      filter: {
        badge: badgeId
      },
      include: 'user',
      page: {
        offset,
        limit: 30
      }
    }
  }).then(response => {
    const users = new Map();
    (response.included || []).forEach(item => item.type === 'users' && users.set(item.id, item));
    const rows = (response.data || []).map(item => {
      const user = users.get(item.relationships?.user?.data?.id);
      return {
        id: item.id,
        grantedAt: item.attributes.grantedAt,
        reason: item.attributes.reason ?? null,
        user: user ? {
          id: user.id,
          username: user.attributes.username,
          displayName: user.attributes.displayName,
          avatarUrl: user.attributes.avatarUrl
        } : null
      };
    });
    return {
      rows,
      hasMore: !!response.links?.next
    };
  });
}

/** Sugestões para o campo de usuário (a busca de usuários do core). */
export function searchUsers(query) {
  return request({
    method: 'GET',
    url: `${apiUrl()}/users`,
    params: {
      filter: {
        q: query
      },
      page: {
        limit: 6
      }
    }
  }).then(response => (response.data || []).map(user => ({
    username: user.attributes.username,
    displayName: user.attributes.displayName
  })));
}
flarum.reg.add('ramon-canela', 'admin/features/badgesAdmin/api', { KEY: KEY,TYPES: TYPES,GROUPINGS: GROUPINGS,apiUrl: apiUrl,hasAdminColumns: hasAdminColumns,errorText: errorText,request: request,loadBadges: loadBadges,saveBadge: saveBadge,deleteBadge: deleteBadge,restoreSystemBadges: restoreSystemBadges,grantBadge: grantBadge,revokeGrant: revokeGrant,loadGrants: loadGrants,searchUsers: searchUsers, });